import sqlite3,pathlib,json,hashlib
root=pathlib.Path('D:/personal/projects/adib-content-studio');before=json.loads((root/'artifacts/ui-preservation-before.json').read_text(encoding='utf8'));db=sqlite3.connect(root/'data/studio.sqlite');rows=dict(db.execute('SELECT id,document FROM studio_items').fetchall());db.close();checks=[{'id':i['id'],'unchanged':i['id'] in rows and hashlib.sha256(rows[i['id']].encode()).hexdigest()==i['hash']} for i in before['items']];result={'backup':before['backup'],'originalCount':len(checks),'currentCount':len(rows),'allOriginalsUnchanged':all(c['unchanged'] for c in checks),'checks':checks};(root/'artifacts/ui-preservation-after.json').write_text(json.dumps(result,indent=2),encoding='utf8');print(json.dumps(result,indent=2));assert result['allOriginalsUnchanged'];assert len(rows)==len(checks)
